    /// @inheritdoc IStreamGovernanceExecutor
    function pruneElapsedTerminalFreezeActions(bytes32 scopeHash)
        external
        override
        returns (uint256 prunedCount)
    {
        prunedCount =
            StreamGovernanceBootstrap.pruneElapsedTerminalFreezeActions(_policy, scopeHash);
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function terminalFreezeActionPage(bytes32 scopeHash, uint256 cursor, uint256 limit)
        external
        view
        override
        returns (bytes32[] memory actionIds, uint64[] memory vetoDeadlines, uint256 nextCursor)
    {
        bytes memory encoded = StreamGovernanceBootstrap.encodeTerminalFreezeActionPage(
            _policy, scopeHash, cursor, limit
        );
        assembly ("memory-safe") {
            return(add(encoded, 0x20), mload(encoded))
        }
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function liveTerminalFreezeActionCount(bytes32 scopeHash)
        external
        view
        override
        returns (uint256)
    {
        return StreamGovernanceBootstrap.liveTerminalFreezeActionCount(_policy, scopeHash);
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function liveTerminalFreezeActionAt(bytes32 scopeHash, uint256 index)
        external
        view
        override
        returns (bytes32 actionId, uint64 vetoDeadline)
    {
        (actionId, vetoDeadline) =
            StreamGovernanceBootstrap.liveTerminalFreezeActionAt(_policy, scopeHash, index);
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function isFreezeSelector(address target, bytes4 selector)
        external
        view
        override
        returns (bool)
    {
        return StreamGovernancePolicy.isFreezeSelector(_policy, target, selector);
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function currentAction()
        external
        view
        override(IStreamGovernanceExecutor, IStreamGovernedParameterAuthority)
        returns (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 scopeHash,
            bytes32 oldValueHash,
            bytes32 newValueHash
        )
    {
        return (
            _executing,
            _currentActionId,
            _currentActionClass,
            _currentScopeHash,
            _currentOldValueHash,
            _currentNewValueHash
        );
    }

    /// @inheritdoc IStreamGovernedParameterAuthority
    function isStreamGovernedParameterAuthority() external pure override returns (bool) {
        return true;
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function scheduledCallDataPointer(bytes32 actionId) external view override returns (address) {
        return _callDataPointers[actionId];
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function scheduledCallData(bytes32 actionId) external view override returns (bytes[] memory) {
        address pointer = _callDataPointers[actionId];
        if (pointer == address(0)) {
            revert GovernanceActionUnknown(actionId);
        }
        return _readCanonicalCallDatas(pointer);
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function systemManifestBatchTailRule(address triggerTarget, bytes4 triggerSelector)
        external
        view
        override
        returns (
            bool registered,
            bytes32 triggerCodeHash,
            uint8 allowedActionClassMask,
            address tailTarget,
            bytes4 tailSelector,
            bytes32 tailCodeHash
        )
    {
        ManifestTailTriggerRule storage rule = _policy.tailRules[triggerTarget][triggerSelector];
        triggerCodeHash = rule.triggerCodeHash;
        registered = triggerCodeHash != bytes32(0);
        allowedActionClassMask = rule.allowedActionClassMask;
        tailTarget = _manifest.systemManifestSatellite;
        tailSelector = SYSTEM_MANIFEST_PUBLISH_SELECTOR;
        tailCodeHash = _manifest.systemManifestSatelliteCodeHash;
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function registerSystemManifestTailTrigger(
        address triggerTarget,
        bytes4 triggerSelector,
        uint8 allowedActionClassMask
    ) external override {
        _requireIsolatedSelfCall(StreamGovernanceActionClasses.TERMINAL_FREEZE);
        if (!_manifest.isSealed) {
            revert SystemManifestBootstrapNotSealed();
        }
        if (_manifest.systemManifestSatellite.codehash != _manifest.systemManifestSatelliteCodeHash)
        {
            revert ManifestTailCodeHashMismatch(
                _manifest.systemManifestSatelliteCodeHash,
                _manifest.systemManifestSatellite.codehash
            );
        }
        if (
            triggerTarget == address(0) || triggerSelector == bytes4(0)
                || triggerTarget.code.length == 0 || allowedActionClassMask == 0
                || (allowedActionClassMask & ~SUPPORTED_MANIFEST_TAIL_ACTION_CLASS_MASK) != 0
                || triggerTarget == address(_manifest.roleRegistry)
                || (triggerTarget == _manifest.systemManifestSatellite
                    && triggerSelector == SYSTEM_MANIFEST_PUBLISH_SELECTOR)
        ) {
            revert InvalidManifestTailTrigger(triggerTarget, triggerSelector);
        }
        if (_policy.tailRules[triggerTarget][triggerSelector].triggerCodeHash != bytes32(0)) {
            revert ManifestTailTriggerAlreadyRegistered(triggerTarget, triggerSelector);
        }
        _appendManifestTailTrigger(
            triggerTarget, triggerSelector, triggerTarget.codehash, allowedActionClassMask, true
        );
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function systemManifestTailTriggerCount() external view override returns (uint256) {
        return _policy.tailEntries.length;
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function systemManifestTailTriggerAt(uint256 index)
        external
        view
        override
        returns (
            address triggerTarget,
            bytes4 triggerSelector,
            bytes32 triggerCodeHash,
            uint8 allowedActionClassMask
        )
    {
        if (index >= _policy.tailEntries.length) {
            revert ManifestTailTriggerIndexOutOfBounds(index);
        }
        ManifestTailTriggerEntry storage entry = _policy.tailEntries[index];
        triggerTarget = entry.triggerTarget;
        triggerSelector = entry.triggerSelector;
        ManifestTailTriggerRule storage rule = _policy.tailRules[triggerTarget][triggerSelector];
        triggerCodeHash = rule.triggerCodeHash;
        allowedActionClassMask = rule.allowedActionClassMask;
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function systemManifestTailTriggerChainHash()
        external
        view
        override
        returns (bytes32 chainHash, uint64 recordCount)
    {
        chainHash = _policy.tailChainHash;
        recordCount = uint64(_policy.tailEntries.length);
    }

    /// @inheritdoc IStreamGovernanceCatalog
    function extendGovernanceActionPolicy(
        uint64 expectedRevision,
        bytes32 expectedOldCatalogHash,
        bytes32 expectedNewCatalogHash,
        GovernanceActionPolicyEntry[] calldata additions
    ) external override {
        _requireSelfCall(StreamGovernanceActionClasses.POINTER_REPLACEMENT);
        StreamGovernanceManifest.extendActionPolicy(
            _manifest,
            _actionPolicy,
            expectedRevision,
            expectedOldCatalogHash,
            expectedNewCatalogHash,
            additions,
            _currentScopeHash,
            _currentOldValueHash,
            _currentNewValueHash
        );
    }

    /// @inheritdoc IStreamGovernanceCatalog
    function governanceActionPolicyState()
        external
        view
        override
        returns (
            bytes32 candidateProfileHash,
            bytes32 catalogHash,
            uint256 entryCount,
            uint64 revision
        )
    {
        return (
            _actionPolicy.candidateProfileHash,
            _actionPolicy.catalogHash,
            _actionPolicy.entries.length,
            _actionPolicy.revision
        );
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function bindSystemManifestBootstrap(SystemManifestBootstrapBinding calldata binding)
        external
        override
        nonReentrant
    {
        if (genesisPlanHash != bytes32(0)) revert GenesisPlanAlreadyCommitted();
        _bindSystemManifestBootstrap(binding);
    }

    function _bindSystemManifestBootstrap(SystemManifestBootstrapBinding calldata binding) private {
        StreamGovernanceManifest.bind(
            _manifest,
            _policy,
            _actionPolicy,
            binding,
            StreamGovernanceManifest.BindContext({
                genesisBootstrapAuthority: genesisBootstrapAuthority,
                governanceNonce: _nonce,
                pendingScheduledActionCount: _pendingScheduledActionCount
            })
        );
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function pendingScheduledActionCount() external view override returns (uint256) {
        return _pendingScheduledActionCount;
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function systemManifestBootstrapState()
        external
        view
        override
        returns (
            bool,
            bool,
            address,
            bytes32,
            address,
            bytes32,
            uint64,
            bytes32,
            uint256,
            bytes32,
            uint64,
            address,
            bytes32,
            address,
            bytes32,
            bytes32,
            uint256,
            bytes32,
            uint256,
            bytes32,
            bytes32,
            uint256,
            bytes32,
            uint256,
            address,
            address,
            bytes32,
            bytes32,
            uint256
        )
    {
        bytes memory encoded = StreamGovernanceManifest.encodeBootstrapState(
            _manifest, genesisBootstrapAuthority
        );
        assembly ("memory-safe") {
            return(add(encoded, 0x20), mload(encoded))
        }
    }

    /// @inheritdoc IStreamGovernanceExecutor
    function sealSystemManifestBootstrap() external override {
        GovernanceAction storage action = _actions[_currentActionId];
        address governanceRoot = StreamGovernanceManifest.prepareSeal(
            _manifest,
            _policy,
            StreamGovernanceManifest.SealContext({
                executing: _executing,
                actionId: _currentActionId,
                actionClass: _currentActionClass,
                batchLength: _currentBatchLength,
                callIndex: _currentCallIndex,
                pendingScheduledActionCount: _pendingScheduledActionCount,
                actionProposer: action.proposer,
                callDataPointer: _callDataPointers[_currentActionId],
                scopeHash: _currentScopeHash,
                oldValueHash: _currentOldValueHash,
                newValueHash: _currentNewValueHash,
                genesisBootstrapAuthority: genesisBootstrapAuthority
            })
        );
        _transferOwnership(governanceRoot);
    }

    function _schedule(
        StreamGovernanceBootstrap.ScheduleContext memory ctx,
        GovernanceCall[] memory calls
    ) private returns (bytes32 actionId) {
        StreamGovernanceScheduling.Prepared memory prepared =
            StreamGovernanceScheduling.prepare(
                _admin,
                _policy,
                _actionPolicy,
                _manifest,
                StreamGovernanceScheduling.Runtime({
                    owner: owner(),
                    bootstrapAuthority: genesisBootstrapAuthority,
                    nonce: _nonce,
                    pendingCount: _pendingScheduledActionCount,
                    executing: _executing,
                    genesisPlanHash: genesisPlanHash,
                    genesisInitialized: genesisInitialized
                }),
                ctx,
                calls
            );
        actionId = prepared.actionId;
        uint256 nonceUsed = _nonce;
        _nonce = nonceUsed + 1;
        StreamGovernanceScheduling.storeAction(_actions[actionId], ctx, calls[0], prepared);

        _actionNonces[actionId] = nonceUsed;
        _actionPolicyCatalogHashes[actionId] = _actionPolicy.catalogHash;
        _callDataPointers[actionId] = prepared.callDataPointer;
        _firstCallTransitionHashes[actionId] =
            [calls[0].scopeHash, calls[0].oldValueHash, calls[0].newValueHash];
        _pendingScheduledActionCount += 1;

        if (ctx.actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            StreamGovernanceBootstrap.appendTerminalFreeze(
                _policy, actionId, ctx.notBefore, calls, msg.sender, prepared.privilegedProposer
            );
            bytes32 guardianConfigCommitment =
                StreamGovernancePolicy.terminalFreezeGuardianConfigCommitment(
                    _manifest.roleRegistry, calls
                );
            _terminalFreezeGuardianConfigCommitments[actionId] = guardianConfigCommitment;
            emit TerminalFreezeGuardianConfigCommitted(
                SCHEMA_VERSION, actionId, guardianConfigCommitment
            );
        }

        StreamGovernanceBootstrap.emitActionScheduled(
            actionId,
            ctx,
            calls[0].target,
            calls[0].selector,
            prepared.totalValue,
            prepared.callsHash,
            nonceUsed
        );
        emit GovernanceActionPolicyValidated(
            SCHEMA_VERSION,
            actionId,
            1,
            _actionPolicy.candidateProfileHash,
            _actionPolicy.catalogHash
        );
    }

    function _publishCallData(bytes[] memory callDatas) private returns (address pointer) {
        return StreamGovernanceBootstrap.publishCallData(_policy, callDatas);
    }

    function _requirePublishedCallData(GovernanceCall[] memory calls)
        private
        view
        returns (address pointer)
    {
        return StreamGovernanceBootstrap.requirePublishedCallData(_policy, calls);
    }

    function _readCanonicalCallDatas(address pointer)
        private
        view
        returns (bytes[] memory callDatas)
    {
        return StreamGovernanceBootstrap.readCanonicalCallDatas(pointer);
    }

    function _requireSelfCall(uint8 requiredClass) private view {
        if (
            msg.sender != address(this) || !_executing || _currentActionId == bytes32(0)
                || _currentActionClass != requiredClass
        ) {
            revert GovernanceSelfCallContextRequired();
        }
    }

    function _requireIsolatedSelfCall(uint8 requiredClass) private view {
        _requireSelfCall(requiredClass);
        if (_currentBatchLength != 1 || _currentCallIndex != 0) {
            revert GovernanceSelfCallContextRequired();
        }
    }

    function _requireCurrentTransition(
        bytes32 scopeHash,
        bytes32 oldValueHash,
        bytes32 newValueHash
    ) private view {
        if (
            _currentScopeHash != scopeHash || _currentOldValueHash != oldValueHash
                || _currentNewValueHash != newValueHash
        ) {
            revert GovernanceTransitionContextMismatch();
        }
    }

    function _policyExecutionContext()
        private
        view
        returns (StreamGovernancePolicy.ExecutionContext memory)
    {
        return StreamGovernancePolicy.ExecutionContext({
            executing: _executing,
            actionId: _currentActionId,
            actionClass: _currentActionClass,
            scopeHash: _currentScopeHash,
            oldValueHash: _currentOldValueHash,
            newValueHash: _currentNewValueHash,
            batchLength: _currentBatchLength,
            callIndex: _currentCallIndex
        });
    }

    function _appendManifestTailTrigger(
        address triggerTarget,
        bytes4 triggerSelector,
        bytes32 triggerCodeHash,
        uint8 allowedActionClassMask,
        bool governed
    ) private {
        StreamGovernanceManifest.appendManifestTailTrigger(
            _policy,
            _manifest,
            triggerTarget,
            triggerSelector,
            triggerCodeHash,
            allowedActionClassMask,
            governed,
            _currentScopeHash,
            _currentOldValueHash,
            _currentNewValueHash
        );
        if (governed) {
            emit SystemManifestTailTriggerRegistered(
                SCHEMA_VERSION,
                triggerTarget,
                triggerSelector,
                triggerCodeHash,
                allowedActionClassMask,
                _manifest.systemManifestSatellite,
                SYSTEM_MANIFEST_PUBLISH_SELECTOR,
                _currentActionId
            );
        }
    }

    function _validateManifestTailComposition(
        bytes32 actionId,
        address proposer,
        uint8 actionClass,
        GovernanceCall[] memory calls,
        bool bootstrapScoped,
        bool scheduling,
        bool privilegedProposer
    ) private {
        StreamGovernanceManifest.validateManifestTailComposition(
            _policy,
            _admin,
            _manifest,
            actionId,
            proposer,
            actionClass,
            calls,
            bootstrapScoped,
            scheduling,
            privilegedProposer,
            this.sealSystemManifestBootstrap.selector,
            this.registerSystemManifestTailTrigger.selector
        );
    }

    function _requireBootstrapCodeHashes() private view {
        StreamGovernanceManifest.requireBootstrapCodeHashes(_manifest);
    }

    function _requireGovernanceRootCodeHash() private view {
        StreamGovernanceManifest.requireGovernanceRootCodeHash(_manifest);
    }

    function _requireBoundRoleRegistry() private view {
        StreamGovernanceManifest.requireBoundRoleRegistry(_manifest);
    }

    function _pruneLiveTerminalFreeze(bytes32 actionId, uint8 actionClass) private {
        if (actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            StreamGovernanceBootstrap.pruneTerminalFreeze(_policy, actionId);
        }
    }

    /// @dev Emits `GovernanceActionScheduled` via `log4`. Non-indexed data is
    ///     ABI-encoded in word chunks: 14 head words (the string head slot at
    ///     index 13 points to offset 0x1C0), then the string length, raw
    ///     bytes, and canonical zero padding.
    function _execute(bytes32 actionId, GovernanceCall[] memory calls, bytes[] memory callDatas)
        private
    {
        uint256 startBalance = address(this).balance;
        GovernanceAction storage action = _actions[actionId];
        (uint256 totalValue, bytes[] memory scheduledCallDatas, bytes32 currentCatalogHash) = StreamGovernanceBootstrap.validateExecution(
            _policy,
            _actionPolicy,
            action,
            StreamGovernanceBootstrap.ExecutionValidationContext({
                actionId: actionId,
                nonce: _actionNonces[actionId],
                callDataPointer: _callDataPointers[actionId],
                scheduledCatalogHash: _actionPolicyCatalogHashes[actionId],
                roleRegistry: address(_manifest.roleRegistry),
                systemManifestSatellite: _manifest.systemManifestSatellite,
                sealSelector: this.sealSystemManifestBootstrap.selector
            }),
            calls,
            callDatas
        );
        bool bootstrapSeal = !_manifest.isSealed && calls.length == 2
            && calls[0].target == address(this)
            && calls[0].selector == this.sealSystemManifestBootstrap.selector;
        _validateManifestTailComposition(
            actionId, action.proposer, action.actionClass, calls, !_manifest.isSealed, false, false
        );
        StreamGovernanceActionPolicy.validateCalls(
            _actionPolicy,
            _manifest.actionPolicyCandidateProfileHash,
            _manifest.actionPolicyCatalogHash,
            _manifest.actionPolicyEntryCount,
            action.actionClass,
            calls,
            scheduledCallDatas
        );
        StreamGovernanceRecoveryPolicy.validate(
            _manifest.core, _manifest.coreCodeHash, action.actionClass, calls, scheduledCallDatas
        );
        if (!_manifest.isSealed && action.proposer != genesisBootstrapAuthority) {
            revert GenesisBootstrapActorRequired(action.proposer);
        }
        if (!_manifest.isSealed) {
            _requireBootstrapCodeHashes();
        } else {
            _requireGovernanceRootCodeHash();
        }
        if (action.actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            _requireBoundRoleRegistry();
            StreamGovernanceBootstrap.validateTerminalFreezeGuardians(_manifest.roleRegistry, calls);
            bytes32 expectedCommitment = _terminalFreezeGuardianConfigCommitments[actionId];
            bytes32 actualCommitment = StreamGovernancePolicy.terminalFreezeGuardianConfigCommitment(
                _manifest.roleRegistry, calls
            );
            if (actualCommitment != expectedCommitment) {
                revert TerminalFreezeGuardianConfigDrift(
                    actionId, expectedCommitment, actualCommitment
                );
            }
        }
        // [GOV-BATCH] rule 2: msg.value equals the exact batch value sum.
        if (msg.value != totalValue) {
            revert BatchValueMismatch(totalValue, msg.value);
        }

        action.status = GovernanceActionStatus.EXECUTED;
        action.executor = msg.sender;
        _pruneLiveTerminalFreeze(actionId, action.actionClass);
        _executing = true;
        _currentActionId = actionId;
        _currentActionClass = action.actionClass;
        _currentBatchLength = calls.length;

        // Governed targets observe these values through currentAction() during
        // each call. Clearing them immediately afterward is the security
        // boundary, not a redundant write.
        // slither-disable-start write-after-write
        for (uint256 i = 0; i < calls.length; i++) {
            _currentCallIndex = i;
            _currentScopeHash = calls[i].scopeHash;
            _currentOldValueHash = calls[i].oldValueHash;
            _currentNewValueHash = calls[i].newValueHash;
            StreamGovernanceBootstrap.executeCall(_policy, actionId, i, calls[i], callDatas[i]);
            _currentScopeHash = bytes32(0);
            _currentOldValueHash = bytes32(0);
            _currentNewValueHash = bytes32(0);
        }
        // slither-disable-end write-after-write

        if (bootstrapSeal) {
            emit SystemManifestBootstrapSealed(
                SCHEMA_VERSION,
                _manifest.bootstrapTriggerSetHash,
                _manifest.expectedTriggerCount,
                _manifest.sealedPayloadPointer,
                _manifest.expectedManifestHash,
                actionId
            );
        }

        _executing = false;
        _currentActionId = bytes32(0);
        _currentActionClass = 0;
        _currentBatchLength = 0;
        _currentCallIndex = 0;
        _pendingScheduledActionCount -= 1;

        // [GOV-BATCH] rule 2: refunded surplus reverts the batch rather than
        // stranding value in the governance contract.
        uint256 expectedBalance = startBalance - totalValue;
        if (address(this).balance != expectedBalance) {
            revert BatchValueSurplus(address(this).balance - expectedBalance);
        }

        emit GovernanceActionExecuted(
            SCHEMA_VERSION,
            actionId,
            action.actionClass,
            action.target,
            action.value,
            action.selector,
            action.callHash,
            action.scopeHash,
            action.oldValueHash,
            action.newValueHash,
            msg.sender,
            action.manifestHash
        );
        emit GovernanceActionPolicyValidated(
            SCHEMA_VERSION, actionId, 2, _actionPolicy.candidateProfileHash, currentCatalogHash
        );
    }

    function _firstSelector(bytes memory callData) private pure returns (bytes4 selector) {
        assembly ("memory-safe") {
            selector := mload(add(callData, 0x20))
        }
    }

    function _callsHash(GovernanceCall[] memory calls) private pure returns (bytes32) {
        return StreamGovernanceBootstrap.governanceCallsHash(calls);
    }

    function _deriveBatchTransitionHashes(GovernanceCall[] memory calls, bytes32 callsHash)
        private
        pure
        returns (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash)
    {
        (scopeHash, oldValueHash, newValueHash) =
            StreamGovernanceBootstrap.deriveBatchTransitionHashes(calls, callsHash);
    }

    function _bytesEqual(bytes memory left, bytes memory right) private pure returns (bool equal) {
        return StreamGovernanceBootstrap.bytesEqual(left, right);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/governance/IStreamGovernanceExecutor.sol";
import "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import "./StreamGovernanceBootstrap.sol";
import "./StreamRoles.sol";

/// @notice Linked policy/state-transition library for Executor-resident
///         governance configuration. Public functions execute by DELEGATECALL,
///         so `address(this)`, `msg.sender`, emitted events, and storage remain
///         those of the Executor while the validation bytecode stays outside
///         its EIP-170 envelope.
library StreamGovernancePolicy {
    uint16 private constant SCHEMA_VERSION = 1;
    bytes32 private constant TERMINAL_GUARDIAN_CONFIG_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_CONFIG_V1");
    bytes32 private constant TERMINAL_GUARDIAN_SCOPE_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_SCOPE_V1");
    bytes32 private constant INITIAL_TERMINAL_GUARDIAN_SET_V1 =
        keccak256("6529STREAM_INITIAL_TERMINAL_GUARDIAN_SET_V1");
    bytes32 private constant TERMINAL_GUARDIAN_HOLDER_V1 =
        keccak256("6529STREAM_TERMINAL_GUARDIAN_HOLDER_V1");
    bytes32 private constant GOVERNANCE_CONFIG_SCOPE_V1 =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_SCOPE_V1");
    bytes32 private constant GOVERNANCE_CONFIG_STATE_V1 =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_STATE_V1");
    bytes32 private constant GOVERNANCE_ROOT_SCOPE_V1 =
        keccak256("6529STREAM_GOVERNANCE_ROOT_SCOPE_V1");
    bytes32 private constant GOVERNANCE_ROOT_STATE_V1 =
        keccak256("6529STREAM_GOVERNANCE_ROOT_STATE_V1");
    bytes32 private constant GOVERNANCE_CONFIG_PROPOSER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_PROPOSER");
    bytes32 private constant GOVERNANCE_CONFIG_CANCELLER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_CANCELLER");
    bytes32 private constant GOVERNANCE_CONFIG_NATIVE_RECEIVER =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_NATIVE_RECEIVER");
    bytes32 private constant GOVERNANCE_CONFIG_TIGHTENING_CALL =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_TIGHTENING_CALL");
    bytes32 private constant GOVERNANCE_CONFIG_FREEZE_SELECTOR =
        keccak256("6529STREAM_GOVERNANCE_CONFIG_FREEZE_SELECTOR");

    struct AdminState {
        mapping(address => bool) proposers;
        mapping(address => bool) cancellers;
        mapping(address => uint64) proposerRevisions;
        mapping(address => uint64) cancellerRevisions;
        mapping(address => uint64) nativeReceiverRevisions;
        mapping(bytes32 => uint64) tighteningCallRevisions;
        mapping(bytes32 => uint64) freezeSelectorRevisions;
        mapping(bytes32 => uint64) actionProposerRevisions;
    }

    struct ExecutionContext {
        bool executing;
        bytes32 actionId;
        uint8 actionClass;
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
        uint256 batchLength;
        uint256 callIndex;
    }

    event GovernanceProposerUpdated(
        uint16 schemaVersion,
        address indexed account,
        bool enabled,
        uint64 revision,
        bytes32 indexed actionId
    );
    event GovernanceCancellerUpdated(
        uint16 schemaVersion,
        address indexed account,
        bool enabled,
        uint64 revision,
        bytes32 indexed actionId
    );
    event ApprovedNativeReceiverUpdated(
        uint16 schemaVersion,
        address indexed receiver,
        bool approved,
        uint64 revision,
        bytes32 indexed actionId
    );
    event TighteningCallUpdated(
        uint16 schemaVersion,
        address indexed target,
        bytes4 indexed selector,
        bool tightening,
        bytes32 targetCodeHash,
        uint64 revision,
        bytes32 indexed actionId
    );
    event FreezeSelectorUpdated(
        uint16 schemaVersion,
        address indexed target,
        bytes4 indexed selector,
        bool freeze,
        bytes32 targetCodeHash,
        uint64 revision,
        bytes32 indexed actionId
    );

    function snapshotActionProposerRevision(
        AdminState storage admin,
        bytes32 actionId,
        address proposer,
        bool privilegedProposer
    ) internal {
        if (!privilegedProposer) {
            admin.actionProposerRevisions[actionId] = admin.proposerRevisions[proposer];
        }
    }

    function requireActionProposerRevision(
        AdminState storage admin,
        bytes32 actionId,
        address proposer
    ) internal view {
        uint64 expected = admin.actionProposerRevisions[actionId];
        if (expected == 0) return;
        uint64 actual = admin.proposerRevisions[proposer];
        bool enabled = admin.proposers[proposer];
        if (!enabled || expected != actual) {
            revert IStreamGovernanceExecutor.GovernanceProposerAuthorizationDrift(
                actionId, proposer, expected, actual, enabled
            );
        }
    }

    function updateProposer(
        AdminState storage admin,
        IStreamRoleRegistry roleRegistry,
        address account,
        bool enabled,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            enabled
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (account == address(0)) revert IStreamGovernanceExecutor.ZeroProposer();
        if (enabled && roleRegistry.hasAnyTerminalFreezeVetoRole(account)) {
            revert IStreamGovernanceExecutor.GovernanceIdentityRoleOverlap(
                account, StreamRoles.ROLE_TERMINAL_FREEZE_VETO
            );
        }
        bool oldEnabled = admin.proposers[account];
        if (oldEnabled == enabled) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_PROPOSER, account, enabled
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_PROPOSER,
            account,
            oldEnabled,
            admin.proposerRevisions[account],
            enabled
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        admin.proposers[account] = enabled;
        admin.proposerRevisions[account] = revision;
        emit GovernanceProposerUpdated(SCHEMA_VERSION, account, enabled, revision, ctx.actionId);
    }

    function updateCanceller(
        AdminState storage admin,
        address account,
        bool enabled,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            enabled
                ? StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
                : StreamGovernanceActionClasses.DELAYED_LOOSENING
        );
        if (account == address(0)) revert IStreamGovernanceExecutor.ZeroCanceller();
        bool oldEnabled = admin.cancellers[account];
        if (oldEnabled == enabled) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_CANCELLER, account, enabled
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_CANCELLER,
            account,
            oldEnabled,
            admin.cancellerRevisions[account],
            enabled
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        admin.cancellers[account] = enabled;
        admin.cancellerRevisions[account] = revision;
        emit GovernanceCancellerUpdated(SCHEMA_VERSION, account, enabled, revision, ctx.actionId);
    }

    function updateNativeReceiver(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address receiver,
        bool approved,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            approved
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (receiver == address(0)) revert IStreamGovernanceExecutor.ZeroNativeReceiver();
        bool oldApproved = policy.approvedNativeReceivers[receiver];
        if (oldApproved == approved) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_NATIVE_RECEIVER, receiver, approved
            );
        }
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceConfigTransitionHashes(
            GOVERNANCE_CONFIG_NATIVE_RECEIVER,
            receiver,
            oldApproved,
            admin.nativeReceiverRevisions[receiver],
            approved
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.approvedNativeReceivers[receiver] = approved;
        admin.nativeReceiverRevisions[receiver] = revision;
        emit ApprovedNativeReceiverUpdated(
            SCHEMA_VERSION, receiver, approved, revision, ctx.actionId
        );
    }

    function updateTighteningCall(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector,
        bool tightening,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            tightening
                ? StreamGovernanceActionClasses.DELAYED_LOOSENING
                : StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
        );
        if (target == address(0)) revert IStreamGovernanceExecutor.ZeroTighteningTarget();
        if (selector == bytes4(0)) {
            revert IStreamGovernanceExecutor.ZeroTighteningSelector();
        }
        if (target == address(this)) {
            revert IStreamGovernanceExecutor.TighteningCallSelfTargetForbidden(selector);
        }
        bool oldEnabled = policy.tighteningCalls[target][selector];
        bytes32 oldCodeHash = policy.tighteningCallCodeHashes[target][selector];
        if (oldEnabled == tightening) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_TIGHTENING_CALL, target, tightening
            );
        }
        if (oldEnabled) _requirePolicyCodeHash(target, selector, oldCodeHash);
        bytes32 newCodeHash = _enabledCodeHash(target, tightening);
        bytes32 key = keccak256(abi.encode(target, selector));
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceSelectorConfigTransitionHashes(
            GOVERNANCE_CONFIG_TIGHTENING_CALL,
            target,
            selector,
            oldEnabled,
            oldCodeHash,
            admin.tighteningCallRevisions[key],
            tightening,
            newCodeHash
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.tighteningCalls[target][selector] = tightening;
        policy.tighteningCallCodeHashes[target][selector] = newCodeHash;
        admin.tighteningCallRevisions[key] = revision;
        emit TighteningCallUpdated(
            SCHEMA_VERSION, target, selector, tightening, newCodeHash, revision, ctx.actionId
        );
    }

    function updateFreezeSelector(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector,
        bool freeze,
        address manifestTailTarget,
        bytes4 manifestTailSelector,
        ExecutionContext memory ctx
    ) public {
        _requireIsolated(
            ctx,
            freeze
                ? StreamGovernanceActionClasses.IMMEDIATE_TIGHTENING
                : StreamGovernanceActionClasses.DELAYED_LOOSENING
        );
        if (target == address(0)) revert IStreamGovernanceExecutor.ZeroFreezeTarget();
        if (selector == bytes4(0)) revert IStreamGovernanceExecutor.ZeroFreezeSelector();
        if (target == address(this)) {
            revert IStreamGovernanceExecutor.FreezeSelectorSelfTargetForbidden(selector);
        }
        if (freeze && target == manifestTailTarget && selector == manifestTailSelector) {
            revert IStreamGovernanceExecutor.InvalidManifestTailTrigger(target, selector);
        }
        if (
            freeze && policy.tailRules[target][selector].triggerCodeHash != bytes32(0)
                && (policy.tailRules[target][selector].allowedActionClassMask & 0x04) == 0
        ) {
            revert IStreamGovernanceExecutor.InvalidManifestTailTrigger(target, selector);
        }
        bool oldEnabled = policy.freezeSelectors[target][selector];
        bytes32 oldCodeHash = policy.freezeSelectorCodeHashes[target][selector];
        if (oldEnabled == freeze) {
            revert IStreamGovernanceExecutor.GovernanceConfigNoOp(
                GOVERNANCE_CONFIG_FREEZE_SELECTOR, target, freeze
            );
        }
        if (oldEnabled) _requirePolicyCodeHash(target, selector, oldCodeHash);
        bytes32 newCodeHash = _enabledCodeHash(target, freeze);
        bytes32 key = keccak256(abi.encode(target, selector));
        (bytes32 scopeHash, bytes32 oldHash, bytes32 newHash, uint64 revision) = governanceSelectorConfigTransitionHashes(
            GOVERNANCE_CONFIG_FREEZE_SELECTOR,
            target,
            selector,
            oldEnabled,
            oldCodeHash,
            admin.freezeSelectorRevisions[key],
            freeze,
            newCodeHash
        );
        _requireTransition(ctx, scopeHash, oldHash, newHash);
        policy.freezeSelectors[target][selector] = freeze;
        policy.freezeSelectorCodeHashes[target][selector] = newCodeHash;
        admin.freezeSelectorRevisions[key] = revision;
        emit FreezeSelectorUpdated(
            SCHEMA_VERSION, target, selector, freeze, newCodeHash, revision, ctx.actionId
        );
    }

    function _enabledCodeHash(address target, bool enabled) private view returns (bytes32) {
        if (!enabled) return bytes32(0);
        bytes32 codeHash = target.codehash;
        if (target.code.length == 0 || codeHash == bytes32(0) || _isEip7702DelegatedEOA(target)) {
            revert IStreamGovernanceExecutor.TargetHasNoCode(0, target);
        }
        return codeHash;
    }

    function _isEip7702DelegatedEOA(address account) private view returns (bool delegated) {
        if (account.code.length != 23) return false;
        bytes3 prefix;
        assembly ("memory-safe") {
            extcodecopy(account, 0, 0, 3)
            prefix := mload(0)
        }
        return prefix == 0xef0100;
    }

    function _requireIsolated(ExecutionContext memory ctx, uint8 requiredClass) private view {
        if (
            msg.sender != address(this) || !ctx.executing || ctx.actionId == bytes32(0)
                || ctx.actionClass != requiredClass || ctx.batchLength != 1 || ctx.callIndex != 0
        ) revert IStreamGovernanceExecutor.GovernanceSelfCallContextRequired();
    }

    function _requireTransition(
        ExecutionContext memory ctx,
        bytes32 scopeHash,
        bytes32 oldValueHash,
        bytes32 newValueHash
    ) private pure {
        if (
            ctx.scopeHash != scopeHash || ctx.oldValueHash != oldValueHash
                || ctx.newValueHash != newValueHash
        ) revert IStreamGovernanceExecutor.GovernanceTransitionContextMismatch();
    }

    function requirePolicyCodeHash(address target, bytes4 selector, bytes32 expectedCodeHash)
        public
        view
    {
        _requirePolicyCodeHash(target, selector, expectedCodeHash);
    }

    function _requirePolicyCodeHash(address target, bytes4 selector, bytes32 expectedCodeHash)
        private
        view
    {
        bytes32 actualCodeHash = target.codehash;
        if (expectedCodeHash == bytes32(0) || actualCodeHash != expectedCodeHash) {
            revert IStreamGovernanceExecutor.GovernancePolicyCodeHashMismatch(
                target, selector, expectedCodeHash, actualCodeHash
            );
        }
    }

    function terminalFreezeGuardianConfigCommitment(
        IStreamRoleRegistry registry,
        GovernanceCall[] memory calls
    ) public view returns (bytes32 commitment) {
        (bytes32 baseChain, uint64 baseRevision) = registry.roleMutationState(
            StreamRoles.ROLE_TERMINAL_FREEZE_VETO
        );
        commitment = keccak256(
            abi.encode(
                TERMINAL_GUARDIAN_CONFIG_V1,
                uint256(block.chainid),
                address(this),
                address(registry),
                address(registry).codehash,
                baseChain,
                baseRevision
            )
        );
        commitment = _appendGuardianHolderCodeHashes(
            registry, StreamRoles.ROLE_TERMINAL_FREEZE_VETO, commitment
        );
        uint256 distinctScopeCount = 0;
        for (uint256 i = 0; i < calls.length; i++) {
            if (_scopeSeenBefore(calls, i, calls[i].scopeHash)) continue;
            bytes32 derivedRole =
                keccak256(abi.encode(StreamRoles.ROLE_TERMINAL_FREEZE_VETO, calls[i].scopeHash));
            (bytes32 scopedChain, uint64 scopedRevision) = registry.roleMutationState(derivedRole);
            commitment = keccak256(
                abi.encode(
                    TERMINAL_GUARDIAN_SCOPE_V1,
                    commitment,
                    calls[i].scopeHash,
                    derivedRole,
                    scopedChain,
                    scopedRevision
                )
            );
            commitment = _appendGuardianHolderCodeHashes(registry, derivedRole, commitment);
            distinctScopeCount++;
        }
        return keccak256(abi.encode(TERMINAL_GUARDIAN_CONFIG_V1, commitment, distinctScopeCount));
    }

    function initialTerminalGuardianSetHash(
        address registry,
        address[] memory guardians,
        bytes32 terminalRoleMutationChain,
        uint64 terminalRoleMutationRevision
    ) public view returns (bytes32 setHash) {
        setHash = keccak256(
            abi.encode(
                INITIAL_TERMINAL_GUARDIAN_SET_V1,
                uint256(block.chainid),
                address(this),
                registry,
                guardians.length,
                terminalRoleMutationChain,
                terminalRoleMutationRevision
            )
        );
        for (uint256 i = 0; i < guardians.length; i++) {
            setHash = keccak256(
                abi.encode(
                    TERMINAL_GUARDIAN_HOLDER_V1, setHash, i, guardians[i], guardians[i].codehash
                )
            );
        }
    }

    function _appendGuardianHolderCodeHashes(
        IStreamRoleRegistry registry,
        bytes32 role,
        bytes32 chainHash
    ) private view returns (bytes32) {
        uint256 holderCount = registry.roleHolderCount(role);
        chainHash = keccak256(abi.encode(TERMINAL_GUARDIAN_HOLDER_V1, chainHash, role, holderCount));
        for (uint256 i = 0; i < holderCount; i++) {
            address holder = registry.roleHolderAt(role, i);
            chainHash = keccak256(
                abi.encode(TERMINAL_GUARDIAN_HOLDER_V1, chainHash, role, i, holder, holder.codehash)
            );
        }
        return chainHash;
    }

    function governanceConfigTransitionHashes(
        bytes32 configKind,
        address key,
        bool oldEnabled,
        uint64 oldRevision,
        bool newEnabled
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(configKind, key);
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_SCOPE_V1, uint256(block.chainid), address(this), configKind, key
            )
        );
        oldStateHash = governanceConfigStateHash(configKind, key, oldEnabled, oldRevision);
        newStateHash = governanceConfigStateHash(configKind, key, newEnabled, newRevision);
    }

    function governanceConfigStateHash(
        bytes32 configKind,
        address key,
        bool enabled,
        uint64 revision
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_STATE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                key,
                enabled,
                revision
            )
        );
    }

    function governanceSelectorConfigTransitionHashes(
        bytes32 configKind,
        address target,
        bytes4 selector,
        bool oldEnabled,
        bytes32 oldCodeHash,
        uint64 oldRevision,
        bool newEnabled,
        bytes32 newCodeHash
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(configKind, target);
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_SCOPE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                target,
                selector
            )
        );
        oldStateHash = governanceSelectorConfigStateHash(
            configKind, target, selector, oldEnabled, oldCodeHash, oldRevision
        );
        newStateHash = governanceSelectorConfigStateHash(
            configKind, target, selector, newEnabled, newCodeHash, newRevision
        );
    }

    function governanceSelectorConfigStateHash(
        bytes32 configKind,
        address target,
        bytes4 selector,
        bool enabled,
        bytes32 targetCodeHash,
        uint64 revision
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                GOVERNANCE_CONFIG_STATE_V1,
                uint256(block.chainid),
                address(this),
                configKind,
                target,
                selector,
                enabled,
                targetCodeHash,
                revision
            )
        );
    }

    function governanceRootTransitionHashes(
        address oldRoot,
        bytes32 oldCodeHash,
        uint64 oldRevision,
        address newRoot,
        bytes32 newCodeHash
    )
        public
        view
        returns (bytes32 scopeHash, bytes32 oldStateHash, bytes32 newStateHash, uint64 newRevision)
    {
        if (oldRevision == type(uint64).max) {
            revert IStreamGovernanceExecutor.GovernanceRevisionOverflow(
                GOVERNANCE_ROOT_STATE_V1, oldRoot
            );
        }
        unchecked {
            newRevision = oldRevision + 1;
        }
        scopeHash = keccak256(
            abi.encode(GOVERNANCE_ROOT_SCOPE_V1, uint256(block.chainid), address(this))
        );
        oldStateHash = governanceRootStateHash(oldRoot, oldCodeHash, oldRevision);
        newStateHash = governanceRootStateHash(newRoot, newCodeHash, newRevision);
    }

    function governanceRootStateHash(address root, bytes32 codeHash, uint64 revision)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                GOVERNANCE_ROOT_STATE_V1,
                uint256(block.chainid),
                address(this),
                root,
                codeHash,
                revision
            )
        );
    }

    function _scopeSeenBefore(
        GovernanceCall[] memory calls,
        uint256 endExclusive,
        bytes32 scopeHash
    ) private pure returns (bool) {
        for (uint256 i = 0; i < endExclusive; i++) {
            if (calls[i].scopeHash == scopeHash) return true;
        }
        return false;
    }

    function proposerConfig(AdminState storage admin, address account)
        public
        view
        returns (bool enabled, uint64 revision, bytes32 stateHash)
    {
        enabled = admin.proposers[account];
        revision = admin.proposerRevisions[account];
        stateHash =
            governanceConfigStateHash(GOVERNANCE_CONFIG_PROPOSER, account, enabled, revision);
    }

    function cancellerConfig(AdminState storage admin, address account)
        public
        view
        returns (bool enabled, uint64 revision, bytes32 stateHash)
    {
        enabled = admin.cancellers[account];
        revision = admin.cancellerRevisions[account];
        stateHash =
            governanceConfigStateHash(GOVERNANCE_CONFIG_CANCELLER, account, enabled, revision);
    }

    function nativeReceiverConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address receiver
    ) public view returns (bool approved, uint64 revision, bytes32 stateHash) {
        approved = policy.approvedNativeReceivers[receiver];
        revision = admin.nativeReceiverRevisions[receiver];
        stateHash = governanceConfigStateHash(
            GOVERNANCE_CONFIG_NATIVE_RECEIVER, receiver, approved, revision
        );
    }

    function tighteningConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector
    )
        public
        view
        returns (bool tightening, bytes32 targetCodeHash, uint64 revision, bytes32 stateHash)
    {
        tightening = policy.tighteningCalls[target][selector];
        targetCodeHash = policy.tighteningCallCodeHashes[target][selector];
        revision = admin.tighteningCallRevisions[keccak256(abi.encode(target, selector))];
        stateHash = governanceSelectorConfigStateHash(
            GOVERNANCE_CONFIG_TIGHTENING_CALL,
            target,
            selector,
            tightening,
            targetCodeHash,
            revision
        );
    }

    function freezeConfig(
        StreamGovernanceBootstrap.PolicyState storage policy,
        AdminState storage admin,
        address target,
        bytes4 selector
    )
        public
        view
        returns (bool freeze, bytes32 targetCodeHash, uint64 revision, bytes32 stateHash)
    {
        freeze = policy.freezeSelectors[target][selector];
        targetCodeHash = policy.freezeSelectorCodeHashes[target][selector];
        revision = admin.freezeSelectorRevisions[keccak256(abi.encode(target, selector))];
        stateHash = governanceSelectorConfigStateHash(
            GOVERNANCE_CONFIG_FREEZE_SELECTOR, target, selector, freeze, targetCodeHash, revision
        );
    }

    function isTighteningCall(
        StreamGovernanceBootstrap.PolicyState storage policy,
        address target,
        bytes4 selector
    ) public view returns (bool tightening) {
        tightening = policy.tighteningCalls[target][selector];
        if (tightening) {
            _requirePolicyCodeHash(
                target, selector, policy.tighteningCallCodeHashes[target][selector]
            );
        }
    }

    function isFreezeSelector(
        StreamGovernanceBootstrap.PolicyState storage policy,
        address target,
        bytes4 selector
    ) public view returns (bool freeze) {
        freeze = policy.freezeSelectors[target][selector];
        if (freeze) {
            _requirePolicyCodeHash(
                target, selector, policy.freezeSelectorCodeHashes[target][selector]
            );
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamGovernanceManifest.sol";
import { StreamGovernanceRecoveryPolicy } from "./StreamGovernanceRecoveryPolicy.sol";

/// @notice Linked scheduling validation and record encoding for the immutable Executor.
/// @dev Storage references point to the Executor's existing fields. This library does
///      not own execution context, counters, or a new storage layout. Public methods
///      run by DELEGATECALL, preserving the original caller and action-ID domain.
library StreamGovernanceScheduling {
    struct Runtime {
        address owner;
        address bootstrapAuthority;
        uint256 nonce;
        uint256 pendingCount;
        bool executing;
        bytes32 genesisPlanHash;
        bool genesisInitialized;
    }

    struct Prepared {
        bytes32 actionId;
        bytes32 callsHash;
        address callDataPointer;
        uint256 totalValue;
        bool privilegedProposer;
    }

    /// @notice Validate the complete schedule before the Executor consumes its nonce.
    function prepare(
        StreamGovernancePolicy.AdminState storage admin,
        StreamGovernanceBootstrap.PolicyState storage policy,
        StreamGovernanceActionPolicy.State storage actionPolicy,
        StreamGovernanceManifest.LifecycleState storage manifest,
        Runtime memory runtime,
        StreamGovernanceBootstrap.ScheduleContext memory ctx,
        GovernanceCall[] memory calls
    ) public returns (Prepared memory prepared) {
        if (runtime.executing) {
            revert IStreamGovernanceExecutor.GovernanceSchedulingDuringExecution();
        }
        if (runtime.genesisPlanHash != bytes32(0) && !runtime.genesisInitialized) {
            revert IStreamGenesisInitializer.InvalidGenesisPlan();
        }
        bool bootstrapAuthority =
            manifest.bound && !manifest.isSealed && msg.sender == runtime.bootstrapAuthority;
        prepared.privilegedProposer = bootstrapAuthority || msg.sender == runtime.owner;
        if (manifest.isSealed) StreamGovernanceManifest.requireGovernanceRootCodeHash(manifest);
        if (!prepared.privilegedProposer && !admin.proposers[msg.sender]) {
            revert IStreamGovernanceExecutor.GovernanceActorNotAuthorized(msg.sender);
        }
        if (!manifest.bound) revert IStreamGovernanceExecutor.SystemManifestBootstrapNotBound();
        if (!manifest.isSealed) {
            if (msg.sender != runtime.bootstrapAuthority) {
                revert IStreamGovernanceExecutor.GenesisBootstrapActorRequired(msg.sender);
            }
            if (runtime.pendingCount != 0) {
                revert IStreamGovernanceExecutor.PendingGovernanceActionExists(runtime.pendingCount);
            }
            StreamGovernanceManifest.requireBootstrapCodeHashes(manifest);
        }

        prepared.callDataPointer = StreamGovernanceBootstrap.requirePublishedCallData(policy, calls);
        bytes[] memory callDatas =
            StreamGovernanceBootstrap.readCanonicalCallDatas(prepared.callDataPointer);
        prepared.totalValue = StreamGovernanceBootstrap.validateCalls(
            policy,
            address(manifest.roleRegistry),
            manifest.systemManifestSatellite,
            ctx.actionClass,
            calls,
            callDatas,
            IStreamGovernanceExecutor.sealSystemManifestBootstrap.selector
        );
        prepared.callsHash = StreamGovernanceBootstrap.governanceCallsHash(calls);
        {
            (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash) =
                StreamGovernanceBootstrap.deriveBatchTransitionHashes(calls, prepared.callsHash);
            if (ctx.scopeHash != scopeHash) {
                revert IStreamGovernanceExecutor.BatchScopeHashMismatch(scopeHash, ctx.scopeHash);
            }
            if (ctx.oldValueHash != oldValueHash) {
                revert IStreamGovernanceExecutor.BatchOldValueHashMismatch(
                    oldValueHash, ctx.oldValueHash
                );
            }
            if (ctx.newValueHash != newValueHash) {
                revert IStreamGovernanceExecutor.BatchNewValueHashMismatch(
                    newValueHash, ctx.newValueHash
                );
            }
        }
        // The atomic committed initializer alone has immediate windows.
        if (runtime.genesisInitialized && !manifest.isSealed) {
            if (!bootstrapAuthority) revert IStreamGenesisInitializer.InvalidGenesisPlan();
        } else {
            StreamGovernanceBootstrap.validateActionWindow(
                ctx.actionClass, ctx.notBefore, ctx.expiresAfter
            );
        }
        prepared.actionId = StreamGovernanceBootstrap.governanceActionId(
            StreamGovernanceBootstrap.ActionIdentity({
                actionClass: ctx.actionClass,
                callsHash: prepared.callsHash,
                scopeHash: ctx.scopeHash,
                oldValueHash: ctx.oldValueHash,
                newValueHash: ctx.newValueHash,
                nonce: runtime.nonce,
                notBefore: ctx.notBefore,
                expiresAfter: ctx.expiresAfter,
                reasonHash: ctx.reasonHash,
                manifestHash: ctx.manifestHash
            })
        );
        StreamGovernanceManifest.validateManifestTailComposition(
            policy,
            admin,
            manifest,
            prepared.actionId,
            msg.sender,
            ctx.actionClass,
            calls,
            !manifest.isSealed,
            true,
            prepared.privilegedProposer,
            IStreamGovernanceExecutor.sealSystemManifestBootstrap.selector,
            IStreamGovernanceExecutor.registerSystemManifestTailTrigger.selector
        );
        StreamGovernanceActionPolicy.validateCalls(
            actionPolicy,
            manifest.actionPolicyCandidateProfileHash,
            manifest.actionPolicyCatalogHash,
            manifest.actionPolicyEntryCount,
            ctx.actionClass,
            calls,
            callDatas
        );
        StreamGovernanceRecoveryPolicy.validate(
            manifest.core, manifest.coreCodeHash, ctx.actionClass, calls, callDatas
        );
        if (ctx.actionClass == StreamGovernanceActionClasses.TERMINAL_FREEZE) {
            StreamGovernanceManifest.requireBoundRoleRegistry(manifest);
            StreamGovernanceBootstrap.validateTerminalFreezeGuardians(manifest.roleRegistry, calls);
        }
    }

    /// @notice Persist the action at its existing mapping slot after validation.
    function storeAction(
        GovernanceAction storage action,
        StreamGovernanceBootstrap.ScheduleContext memory ctx,
        GovernanceCall memory firstCall,
        Prepared memory prepared
    ) public {
        if (action.status != GovernanceActionStatus.NONE) {
            revert IStreamGovernanceExecutor.GovernanceActionNotScheduled(prepared.actionId);
        }
        action.status = GovernanceActionStatus.SCHEDULED;
        action.actionClass = ctx.actionClass;
        action.target = firstCall.target;
        action.value = prepared.totalValue;
        action.selector = firstCall.selector;
        action.callHash = prepared.callsHash;
        action.scopeHash = ctx.scopeHash;
        action.oldValueHash = ctx.oldValueHash;
        action.newValueHash = ctx.newValueHash;
        action.notBefore = ctx.notBefore;
        action.expiresAfter = ctx.expiresAfter;
        action.proposer = msg.sender;
        action.reasonHash = ctx.reasonHash;
        action.reasonURI = ctx.reasonURI;
        action.manifestHash = ctx.manifestHash;
    }
}

