// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../libraries/SSTORE2.sol";

/// @notice Permissionless byte publication, with no schema or record authority.
/// @dev Registry acceptance is separate. Unregistered uploads do not enter its document index.
contract StreamSchemaDocumentStore {
    uint256 public constant MAX_CHUNK_BYTES = 8192;

    struct Chunk {
        address pointer;
        uint32 length;
    }
    mapping(bytes32 => Chunk) public chunk;
    error InvalidChunkLength(uint256 length);
    error UnknownChunk(bytes32 hash);
    error ChangedChunk(bytes32 hash);
    event ChunkPublished(bytes32 indexed hash, address indexed pointer, uint32 length);

    function publishChunk(bytes calldata payload) external returns (bytes32 hash, address pointer) {
        if (payload.length == 0 || payload.length > MAX_CHUNK_BYTES) {
            revert InvalidChunkLength(payload.length);
        }
        hash = keccak256(payload);
        pointer = chunk[hash].pointer;
        if (pointer != address(0)) return (hash, pointer);
        pointer = SSTORE2.write(payload);
        chunk[hash] = Chunk(pointer, uint32(payload.length));
        emit ChunkPublished(hash, pointer, uint32(payload.length));
    }

    function readChunk(bytes32 hash) external view returns (bytes memory payload) {
        Chunk memory row = chunk[hash];
        if (row.pointer == address(0)) revert UnknownChunk(hash);
        payload = SSTORE2.read(row.pointer);
        if (payload.length != row.length || keccak256(payload) != hash) revert ChangedChunk(hash);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";
import "./StreamSchemaDocumentStore.sol";

/// @notice Governance-approved schema, canonicalization, catalog and dependency bytes.
/// @dev JSON and ontology meaning are validated by the pinned publication tooling. This host
///      verifies exact retained bytes, immutable identity/lineage and executing governance.
contract StreamSchemaRegistry is IStreamSchemaRegistry, IStreamSchemaDocumentFacts {
    uint256 public constant MAX_DOCUMENT_CHUNKS = 64;
    uint256 public constant CHUNK_BYTES = 8192;
    uint256 public constant MAX_DOCUMENT_BYTES = MAX_DOCUMENT_CHUNKS * CHUNK_BYTES;
    bytes32 public constant RAW_BYTES = keccak256("RAW_BYTES");
    string public constant RAW_BYTES_DEFINITION =
        '{"name":"RAW_BYTES","rule":"Do not transform the supplied bytes.","version":1}';
    bytes32 private constant _SCOPE = keccak256("6529STREAM_SCHEMA_DOCUMENT_SCOPE_V1");
    bytes32 private constant _STATE = keccak256("6529STREAM_SCHEMA_DOCUMENT_STATE_V1");
    address public immutable override governanceAuthority;
    bytes32 public immutable governanceAuthorityCodeHash;
    address public immutable override chunkStore;

    struct PayloadPointer {
        address pointer;
        bytes32 family;
        bytes32 hash;
    }
    mapping(bytes32 => DocumentView) private _documents;
    bytes32[] private _ids;
    PayloadPointer[] private _pointers;
    mapping(bytes32 => bool) private _acceptedPointers;

    constructor(address executor) {
        if (
            executor.code.length == 0
                || !IStreamGovernedParameterAuthority(executor).isStreamGovernedParameterAuthority()
        ) {
            revert UnauthorizedDocumentGovernance();
        }
        governanceAuthority = executor;
        governanceAuthorityCodeHash = executor.codehash;
        chunkStore = address(new StreamSchemaDocumentStore());
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IStreamSchemaRegistry).interfaceId
            || id == type(IStreamSchemaDocumentFacts).interfaceId || id == 0x01ffc9a7;
    }

    function registerDocument(DocumentSpec calldata specification, bytes32[] calldata chunkHashes)
        external
        override
        returns (bytes32 documentId)
    {
        documentId = keccak256(bytes(specification.name));
        _validateSpecification(specification, documentId);
        if (_documents[documentId].exists) revert DocumentAlreadyRegistered(documentId);
        _validatePayload(specification, chunkHashes);
        bytes32 declaration = keccak256(abi.encode(specification, chunkHashes));
        bytes32 actionId = _governed(
            _scope(documentId),
            _state(false, 0, DocumentStatus.ACTIVE),
            _state(true, declaration, DocumentStatus.ACTIVE)
        );
        DocumentView storage row = _documents[documentId];
        row.exists = true;
        row.declarationHash = declaration;
        row.specification = specification;
        row.chunkHashes = chunkHashes;
        _ids.push(documentId);
        bytes32 family =
            keccak256(abi.encode("STREAM_INTERPRETATION_DOCUMENT_CHUNK_V1", specification.kind));
        for (uint256 i; i < chunkHashes.length; ++i) {
            bytes32 key = keccak256(abi.encode(family, chunkHashes[i]));
            if (_acceptedPointers[key]) continue;
            _acceptedPointers[key] = true;
            (address pointer,) = StreamSchemaDocumentStore(chunkStore).chunk(chunkHashes[i]);
            _pointers.push(PayloadPointer(pointer, family, chunkHashes[i]));
        }
        emit DocumentRegistered(
            1,
            documentId,
            specification.contentHash,
            actionId,
            declaration,
            specification,
            chunkHashes
        );
    }

    function setDocumentStatus(bytes32 documentId, DocumentStatus next) external override {
        DocumentView storage row = _documents[documentId];
        if (!row.exists) revert DocumentUnknown(documentId);
        if (documentId == RAW_BYTES || uint8(next) <= uint8(row.status)) {
            revert InvalidDocumentStatus();
        }
        bytes32 actionId = _governed(
            _scope(documentId),
            _state(true, row.declarationHash, row.status),
            _state(true, row.declarationHash, next)
        );
        DocumentStatus previous = row.status;
        row.status = next;
        emit DocumentStatusChanged(1, documentId, previous, next, actionId);
    }

    function document(bytes32 id) external view override returns (DocumentView memory) {
        return _documents[id];
    }

    function documentFacts(bytes32 id) external view override returns (DocumentFacts memory facts) {
        DocumentView storage row = _documents[id];
        facts.exists = row.exists;
        facts.kind = row.specification.kind;
        facts.status = row.status;
        facts.contentHash = row.specification.contentHash;
        facts.canonicalizationId = row.specification.canonicalizationId;
        facts.supersedesId = row.specification.supersedesId;
        facts.totalBytes = row.specification.totalBytes;
        facts.chunkCount = row.chunkHashes.length;
        facts.declarationHash = row.declarationHash;
    }

    function documentChunkHashAt(bytes32 id, uint256 index)
        external
        view
        override
        returns (bytes32)
    {
        DocumentView storage row = _documents[id];
        if (!row.exists) revert DocumentUnknown(id);
        return row.chunkHashes[index];
    }

    function documentBytes(bytes32 id) external view override returns (bytes memory payload) {
        DocumentView storage row = _documents[id];
        if (!row.exists) revert DocumentUnknown(id);
        payload = _assemble(row.chunkHashes, row.specification.totalBytes);
        bytes32 actual = keccak256(payload);
        if (actual != row.specification.contentHash) {
            revert DocumentHashMismatch(row.specification.contentHash, actual);
        }
    }

    function documentCount() external view override returns (uint256) {
        return _ids.length;
    }

    function documentIdAt(uint256 index) external view override returns (bytes32) {
        return _ids[index];
    }

    function payloadPointerCount(uint256 scopeKey) external view override returns (uint256) {
        if (scopeKey != 0) revert InvalidDocumentScope(scopeKey);
        return _pointers.length;
    }

    function payloadPointerAt(uint256 scopeKey, uint256 index)
        external
        view
        override
        returns (address pointer, bytes32 payloadFamily, bytes32 contentHash)
    {
        if (scopeKey != 0) revert InvalidDocumentScope(scopeKey);
        PayloadPointer storage row = _pointers[index];
        return (row.pointer, row.family, row.hash);
    }

    function registrationTransition(
        DocumentSpec calldata specification,
        bytes32[] calldata chunkHashes
    ) external view override returns (bytes32, bytes32, bytes32) {
        bytes32 id = keccak256(bytes(specification.name));
        _validateSpecification(specification, id);
        if (_documents[id].exists) revert DocumentAlreadyRegistered(id);
        _validatePayload(specification, chunkHashes);
        return (
            _scope(id),
            _state(false, 0, DocumentStatus.ACTIVE),
            _state(true, keccak256(abi.encode(specification, chunkHashes)), DocumentStatus.ACTIVE)
        );
    }

    function statusTransition(bytes32 id, DocumentStatus next)
        external
        view
        override
        returns (bytes32, bytes32, bytes32)
    {
        DocumentView storage row = _documents[id];
        if (!row.exists) revert DocumentUnknown(id);
        if (id == RAW_BYTES || uint8(next) <= uint8(row.status)) revert InvalidDocumentStatus();
        return (
            _scope(id),
            _state(true, row.declarationHash, row.status),
            _state(true, row.declarationHash, next)
        );
    }

    function _validateSpecification(DocumentSpec calldata spec, bytes32 id) private view {
        bytes memory name = bytes(spec.name);
        if (
            name.length == 0 || name.length > 128 || spec.contentHash == bytes32(0)
                || bytes(spec.uri).length > 2048 || spec.totalBytes == 0
                || spec.totalBytes > MAX_DOCUMENT_BYTES
        ) {
            revert InvalidDocument();
        }
        for (uint256 i; i < name.length; ++i) {
            bytes1 c = name[i];
            if (!((c >= 0x41 && c <= 0x5a) || (c >= 0x61 && c <= 0x7a) || (c >= 0x30 && c <= 0x39)
                        || c == 0x5f || c == 0x2d || c == 0x2e)) revert InvalidDocument();
        }
        if (id == RAW_BYTES) {
            // The one bootstrap definition has fixed bytes and cannot shadow another kind.
            if (
                spec.kind != DocumentKind.CANONICALIZATION || spec.canonicalizationId != RAW_BYTES
                    || spec.supersedesId != 0
                    || spec.contentHash != keccak256(bytes(RAW_BYTES_DEFINITION))
            ) {
                revert InvalidCanonicalization(spec.canonicalizationId);
            }
        } else {
            DocumentView storage canonical = _documents[spec.canonicalizationId];
            if (
                !canonical.exists || canonical.specification.kind != DocumentKind.CANONICALIZATION
                    || canonical.status != DocumentStatus.ACTIVE
            ) revert InvalidCanonicalization(spec.canonicalizationId);
        }
        if (
            spec.supersedesId != 0
                && (spec.supersedesId == id
                    || !_documents[spec.supersedesId].exists
                    || _documents[spec.supersedesId].specification.kind != spec.kind)
        ) {
            revert InvalidDocumentPredecessor(spec.supersedesId);
        }
    }

    function _validatePayload(DocumentSpec calldata spec, bytes32[] calldata hashes) private view {
        bytes32 actual = keccak256(_assemble(hashes, spec.totalBytes));
        if (actual != spec.contentHash) revert DocumentHashMismatch(spec.contentHash, actual);
    }

    function _assemble(bytes32[] memory hashes, uint256 total)
        private
        view
        returns (bytes memory payload)
    {
        if (
            hashes.length == 0 || hashes.length > MAX_DOCUMENT_CHUNKS || total == 0
                || total > MAX_DOCUMENT_BYTES
        ) revert InvalidDocument();
        payload = new bytes(total);
        uint256 offset;
        for (uint256 i; i < hashes.length; ++i) {
            bytes memory part = StreamSchemaDocumentStore(chunkStore).readChunk(hashes[i]);
            if (
                part.length == 0 || part.length > CHUNK_BYTES
                    || (i + 1 < hashes.length && part.length != CHUNK_BYTES)
                    || offset + part.length > total
            ) revert InvalidDocument();
            // The final word may include allocation padding, never bytes beyond the payload's length.
            assembly ("memory-safe") {
                let length := mload(part)
                let source := add(part, 32)
                let destination := add(add(payload, 32), offset)
                for { let j := 0 } lt(j, length) { j := add(j, 32) } {
                    mstore(add(destination, j), mload(add(source, j)))
                }
            }
            offset += part.length;
        }
        if (offset != total) revert InvalidDocument();
    }

    function _scope(bytes32 id) private view returns (bytes32) {
        return keccak256(abi.encode(_SCOPE, block.chainid, address(this), id));
    }

    function _state(bool exists, bytes32 declaration, DocumentStatus status)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(_STATE, exists, declaration, status));
    }

    function _governed(bytes32 scope, bytes32 oldHash, bytes32 newHash)
        private
        view
        returns (bytes32 id)
    {
        if (msg.sender != governanceAuthority || msg.sender.codehash != governanceAuthorityCodeHash)
        {
            revert UnauthorizedDocumentGovernance();
        }
        (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 actualScope,
            bytes32 actualOld,
            bytes32 actualNew
        ) = IStreamGovernedParameterAuthority(governanceAuthority).currentAction();
        if (
            !executing || actionId == 0 || actionClass != 1 || actualScope != scope
                || actualOld != oldHash || actualNew != newHash
        ) {
            revert UnauthorizedDocumentGovernance();
        }
        return actionId;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    IStreamC2PAReconciliation as C
} from "../../interfaces/stream/metadata/IStreamC2PAReconciliation.sol";
import { Strings } from "../../vendor/openzeppelin/Strings.sol";
import {
    IStreamC2PAConflicts as F
} from "../../interfaces/stream/metadata/IStreamC2PAConflicts.sol";

/// @notice Closed typed fields only; no supplied report text enters JSON.
library StreamStaticC2PAJSON {
    using Strings for uint256;

    function fields(C.Display memory d, bytes32 subject, bool unavailable)
        internal
        pure
        returns (bytes memory)
    {
        if (d.recordHash == 0 && !unavailable) return "";
        uint8 divergence = !d.current
            ? 2
            : d.authorship == C.AuthorshipStatus.DIVERGENT
                ? 1
                : d.authorship == C.AuthorshipStatus.CONSISTENT ? 0 : 2;
        return _fields(d, subject, unavailable, divergence);
    }

    function withConflicts(
        C.Display memory d,
        bytes32 subject,
        bool unavailable,
        F.Standing memory token,
        F.Standing memory collection,
        bool conflictUnavailable
    ) internal pure returns (bytes memory) {
        if (
            d.recordHash == 0 && !unavailable && !conflictUnavailable && token.revision == 0
                && collection.revision == 0
        ) return "";
        bool standing = token.unresolvedCount != 0 || collection.unresolvedCount != 0;
        uint8 divergence = standing ? 1 : conflictUnavailable ? 2 : 0;
        // A positive current report remains adverse even when the independent conflict read fails.
        if (conflictUnavailable && d.current && d.authorship == C.AuthorshipStatus.DIVERGENT) {
            divergence = 1;
        }
        return abi.encodePacked(
            _fields(d, subject, unavailable, divergence),
            ',"c2pa_conflict_read_unavailable":',
            conflictUnavailable ? "true" : "false",
            ',"c2pa_conflict_state":"',
            conflictUnavailable
                ? "unavailable"
                : standing
                    ? "standing"
                    : token.revision != 0 || collection.revision != 0 ? "acknowledged" : "none",
            '"',
            _conflictFields("token", token),
            _conflictFields("collection", collection)
        );
    }

    function _conflictFields(string memory scope, F.Standing memory v)
        private
        pure
        returns (bytes memory)
    {
        return abi.encodePacked(
            ',"c2pa_',
            scope,
            '_conflict":"',
            uint256(v.conflictId).toHexString(32),
            '","c2pa_',
            scope,
            '_divergence_record":"',
            uint256(v.recordHash).toHexString(32),
            '","c2pa_',
            scope,
            '_conflict_chain":"',
            uint256(v.chainHash).toHexString(32),
            '","c2pa_',
            scope,
            '_unresolved_count":"',
            uint256(v.unresolvedCount).toString(),
            '"'
        );
    }

    function _fields(C.Display memory d, bytes32 subject, bool unavailable, uint8 divergence)
        private
        pure
        returns (bytes memory)
    {
        if (!d.current) {
            d.validation = C.ValidationStatus.UNEVALUATED;
            d.authorship = C.AuthorshipStatus.UNEVALUATED;
        }
        return abi.encodePacked(
            ',"c2pa_validation_status":"',
            d.validation == C.ValidationStatus.VALID
                ? "valid"
                : d.validation == C.ValidationStatus.INVALID ? "invalid" : "unevaluated",
            '","c2pa_authorship_status":"',
            d.authorship == C.AuthorshipStatus.CONSISTENT
                ? "consistent"
                : d.authorship == C.AuthorshipStatus.DIVERGENT ? "divergent" : "unevaluated",
            '","c2pa_attribution_divergence":',
            divergence == 1 ? "true" : divergence == 0 ? "false" : "null",
            ',"c2pa_basis":"selected_verifier_report","c2pa_report_current":',
            d.current ? "true" : "false",
            ',"c2pa_read_unavailable":',
            unavailable ? "true" : "false",
            ',"c2pa_record":"',
            uint256(d.recordHash).toHexString(32),
            '","c2pa_subject":"',
            uint256(subject).toHexString(32),
            '"'
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { IStreamRenderer as R } from "../../interfaces/stream/metadata/IStreamRenderer.sol";
import {
    IStreamStaticMetadataRouter as S
} from "../../interfaces/stream/metadata/IStreamStaticMetadataRouter.sol";
import {
    IStreamScriptBundles as B
} from "../../interfaces/stream/metadata/IStreamScriptBundles.sol";
import { StreamRenderContextV1 as Context } from "./StreamRenderContextV1.sol";
import { Strings } from "../../vendor/openzeppelin/Strings.sol";
import { Base64 } from "../../vendor/openzeppelin/Base64.sol";
import {
    IStreamC2PAReconciliation as C2PA
} from "../../interfaces/stream/metadata/IStreamC2PAReconciliation.sol";
import { StreamStaticC2PAJSON } from "./StreamStaticC2PAJSON.sol";
import { StreamMetadataCitation as Citation } from "./StreamMetadataCitation.sol";
import {
    IStreamC2PAConflicts as Conflicts
} from "../../interfaces/stream/metadata/IStreamC2PAConflicts.sol";

/// @notice Fixed pure Metadata companion; consumes authenticated renderer input and makes no external read.
/// @dev Its address/runtime/selector belong to the version's transitive declared read set.
library StreamStaticRenderEncoding {
    using Strings for uint256;
    bytes32 private constant ID = keccak256("6529STREAM_RENDERER_V1");
    bytes32 private constant VERSION = keccak256("6529STREAM_STATIC_RENDERER_V1");
    bytes32 private constant CONTEXT = keccak256("STREAM_CONTEXT_V1");
    uint256 private constant MAX_DEFAULT_URI_BYTES = 24576;
    uint256 private constant MAX_FULL_BYTES = 16777216;
    error InvalidStaticRender();
    error StaticOutputTooLarge();

    struct Prepared {
        S.RawSource source;
        R.MetadataConfig config;
        Context.Facts facts;
        bytes32 bundle;
        B.Facts bundleFacts;
        bytes artist;
        C2PA.Display c2pa;
        bytes32 c2paSubject;
        bool c2paUnavailable;
        Conflicts.Standing c2paTokenConflict;
        Conflicts.Standing c2paCollectionConflict;
        bool c2paConflictsEnabled;
        bool c2paConflictsUnavailable;
    }

    function _c2pa(Prepared memory p) private pure returns (bytes memory) {
        if (!p.c2paConflictsEnabled) {
            return StreamStaticC2PAJSON.fields(p.c2pa, p.c2paSubject, p.c2paUnavailable);
        }
        return StreamStaticC2PAJSON.withConflicts(
            p.c2pa,
            p.c2paSubject,
            p.c2paUnavailable,
            p.c2paTokenConflict,
            p.c2paCollectionConflict,
            p.c2paConflictsUnavailable
        );
    }

    function render(
        R.RenderRequest memory r,
        Prepared memory p,
        string memory script,
        address router,
        uint8 mode
    ) public pure returns (string memory) {
        return _render(r, p, script, router, mode, false);
    }

    /// @notice Separately admitted current JSON; original render remains byte-compatible.
    function renderCurrent(
        R.RenderRequest memory r,
        Prepared memory p,
        string memory script,
        address router,
        uint8 mode
    ) public pure returns (string memory) {
        return _render(r, p, script, router, mode, true);
    }

    function _render(
        R.RenderRequest memory r,
        Prepared memory p,
        string memory script,
        address router,
        uint8 mode,
        bool current
    ) private pure returns (string memory) {
        bool full = mode >= 2;
        string memory context = Context.json(r, p.facts, ID, VERSION);
        string memory html;
        if (
            r.state != R.TokenRenderState.PENDING_RANDOMNESS
                && p.config.mode != R.MetadataMode.OFFCHAIN && (full || p.bundle == 0)
        ) {
            html = Context.html(context, p.facts.dependencyScript, script);
            if (bytes(html).length > MAX_FULL_BYTES) revert StaticOutputTooLarge();
        }
        if (mode == 3) return bytes(html).length == 0 ? Context.html(context, "", "") : html;
        // A large program is available at the actual full methods. Its compact reference is
        // never described as a complete executable export. No external URI is executed here.
        if (current) {
            context = Citation.inObject(context, Citation.work(p.source.chainId, r.core, r.tokenId));
        }
        bytes memory json = _json(r, p, context, html, full, router);
        if (!full && (p.bundle != 0 || json.length > 18000)) {
            json = _compact(r, p, router, current);
        }
        if (json.length > (full ? MAX_FULL_BYTES : 18000)) revert StaticOutputTooLarge();
        if (mode == 1) {
            string memory uri = string.concat("data:application/json;base64,", Base64.encode(json));
            if (bytes(uri).length > MAX_DEFAULT_URI_BYTES) revert StaticOutputTooLarge();
            return uri;
        }
        return string(json);
    }

    function _json(
        R.RenderRequest memory r,
        Prepared memory p,
        string memory context,
        string memory html,
        bool full,
        address router
    ) private pure returns (bytes memory) {
        string memory fullPrefix = string.concat(
            "web3://", uint256(uint160(router)).toHexString(20), ":", p.source.chainId.toString()
        );
        string memory animation;
        if (bytes(html).length != 0) {
            // The fixed prefix and Base64 alphabet contain no JSON escape characters.
            animation = string.concat("data:text/html;base64,", Base64.encode(bytes(html)));
        } else if (bytes(p.source.animationBaseURI).length != 0) {
            animation =
                Context.escape(string.concat(p.source.animationBaseURI, r.tokenId.toString()));
        }
        bytes memory out = abi.encodePacked(
            '{"name":"',
            Context.escape(bytes(p.source.name).length == 0 ? "6529 Stream" : p.source.name),
            " #",
            r.collectionSerial.toString(),
            '","description":"',
            Context.escape(p.source.description),
            '","image":"',
            Context.escape(p.source.imageURI),
            '","animation_url":"',
            animation,
            '","metadata_state":"',
            _renderState(r.state),
            '","metadata_schema_version":"6529stream-static-v1","token_data_base64":"',
            Base64.encode(p.facts.tokenData),
            '","properties":{"stream":',
            context,
            ',"provenance":{"attribution":',
            p.artist,
            _c2pa(p),
            '},"render_mode":"',
            full ? "full" : "marketplace",
            '","config_record_hash":"',
            uint256(r.metadataSnapshotHash).toHexString(32),
            '","views":{"tokenJSON":"',
            fullPrefix,
            "/tokenJSON/",
            r.tokenId.toString(),
            '","tokenHTML":"',
            fullPrefix,
            "/tokenHTML/",
            r.tokenId.toString(),
            '"}'
        );
        if (p.config.mode != R.MetadataMode.ONCHAIN) {
            out = bytes.concat(
                out,
                abi.encodePacked(
                    ',"offchain_metadata_uri":"',
                    Context.escape(
                        string.concat(
                            p.config.baseURI,
                            (p.config.offchainURIIdMode == R.OffchainURIIdMode.TOKEN_ID
                                    ? r.tokenId
                                    : r.collectionSerial)
                            .toString()
                        )
                    ),
                    '"'
                )
            );
        }
        return bytes.concat(out, bytes("}}"));
    }

    function _renderState(R.TokenRenderState state) private pure returns (string memory) {
        return state == R.TokenRenderState.BURNED
            ? "burned"
            : state == R.TokenRenderState.PENDING_RANDOMNESS
                ? "pending"
                : state == R.TokenRenderState.FROZEN ? "frozen" : "active";
    }

    function _compact(R.RenderRequest memory r, Prepared memory p, address router, bool current)
        private
        pure
        returns (bytes memory)
    {
        string memory root = string.concat(
            "web3://", uint256(uint160(router)).toHexString(20), ":", p.source.chainId.toString()
        );
        bytes memory artist = p.artist;
        if (artist.length > 8192) {
            // The complete object begins with the canonical state field. Retain that actual
            // state while linking the full object; truncation is never mislabeled unavailable.
            bytes memory prefix = bytes('{"state":"');
            uint256 end = prefix.length;
            if (artist.length < prefix.length) revert InvalidStaticRender();
            for (uint256 i; i < prefix.length; ++i) {
                if (artist[i] != prefix[i]) revert InvalidStaticRender();
            }
            while (end < artist.length && artist[end] != 0x22 && end < 64) ++end;
            if (end == artist.length || end == 64) revert InvalidStaticRender();
            bytes memory state = new bytes(end);
            for (uint256 i; i < end; ++i) {
                state[i] = artist[i];
            }
            artist = abi.encodePacked(state, '","details_location":"tokenJSON"}');
        }
        return abi.encodePacked(
            '{"name":"',
            Context.escape(p.source.name),
            " #",
            r.collectionSerial.toString(),
            '","image":"',
            Context.escape(p.source.imageURI),
            '","metadata_state":"',
            _renderState(r.state),
            '","metadata_schema_version":"6529stream-static-v1","token_data_location":"tokenJSON:token_data_base64","properties":{',
            current
                ? abi.encodePacked(
                    '"stream":{"citation":"',
                    Citation.work(p.source.chainId, r.core, r.tokenId),
                    '"},'
                )
                : bytes(""),
            '"render_mode":"compact","renderer_id":"',
            uint256(ID).toHexString(32),
            '","renderer_version":"',
            uint256(VERSION).toHexString(32),
            '","context_version":"',
            uint256(CONTEXT).toHexString(32),
            '","config_record_hash":"',
            uint256(r.metadataSnapshotHash).toHexString(32),
            '","script_hash":"',
            uint256(p.facts.scriptHash).toHexString(32),
            '","dependency_hash":"',
            uint256(p.facts.dependencyHash).toHexString(32),
            '","provenance":{"attribution":',
            artist,
            _c2pa(p),
            '},"views":{"tokenJSON":"',
            root,
            "/tokenJSON/",
            r.tokenId.toString(),
            '","tokenHTML":"',
            root,
            "/tokenHTML/",
            r.tokenId.toString(),
            '"}}}'
        );
    }
}

