        bytes32 scriptHash;
        bytes32 rendererCompatibility;
        PayloadSourceType sourceType;
        string libraryURI;
        string scriptURI;
        string sourcePointer;
        string mimeType;
        uint256 chunkCount;
        bool executable;
    }

