        PayloadSourceType contentSourceType;
        string contentURI;
        bytes32 contentHash;
        string contentMimeType;
        string manifestURI;
        bytes32 manifestHash;
        string alternatesURI;
        bytes32 alternatesHash;
    }

    struct Selection {
        address host;
        bytes32 codeHash;
        bytes32 manifestHash;
    }
}

